#!/usr/bin/env python3
"""统计 CSV 文件每一列的非空值数量。"""
import csv
import sys
from collections import Counter


def count_non_empty(path: str) -> Counter:
    counts: Counter = Counter()
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        if reader.fieldnames is None:
            print("CSV 文件为空或缺少表头", file=sys.stderr)
            sys.exit(1)
        counts.update({name: 0 for name in reader.fieldnames})
        for row in reader:
            for name in reader.fieldnames:
                value = (row.get(name) or "").strip()
                if value:
                    counts[name] += 1
    return counts


def main() -> None:
    if len(sys.argv) != 2:
        print(f"用法: {sys.argv[0]} <csv文件>", file=sys.stderr)
        sys.exit(1)
    for name, count in count_non_empty(sys.argv[1]).items():
        print(f"{name}: {count}")


if __name__ == "__main__":
    main()
